# Browser GPS tracker: a tiny inline Streamlit component, so no third frontend file is needed.
COMPONENT_DIR = Path(tempfile.gettempdir()) / "family_forest_gps_component"
COMPONENT_DIR.mkdir(parents=True, exist_ok=True)
COMPONENT_HTML = r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,'Noto Sans KR',sans-serif;background:transparent;color:#f8f4e7}.row{height:88px;border:1px solid rgba(238,220,168,.25);border-radius:18px;background:linear-gradient(105deg,#203e2e,#31563b);display:flex;align-items:center;gap:15px;padding:12px 16px}.orb{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:#d8ed9c;color:#304826;font-size:22px;flex:none}.copy{flex:1;min-width:0}.title{font-weight:800;font-size:15px;line-height:1.3}.desc{font-size:11px;color:#d4dec9;margin-top:4px;line-height:1.35}.btn{border:0;border-radius:12px;background:#d5ef91;color:#294323;font-weight:900;font-size:13px;padding:13px 17px;cursor:pointer;white-space:nowrap}.btn.stop{background:#fae0c1;color:#6b3829}.live{display:none;color:#d5ef91;font-size:12px;font-weight:800;white-space:nowrap}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#9bea61;margin-right:6px;box-shadow:0 0 0 4px rgba(155,234,97,.15);animation:pulse 1.4s infinite}@keyframes pulse{50%{opacity:.38;transform:scale(.75)}}@media(max-width:520px){.row{height:auto;min-height:88px;gap:10px;padding:11px}.orb{width:40px;height:40px}.desc{font-size:10px}.btn{padding:12px 11px;font-size:12px}}
</style></head><body><div class="row"><div class="orb" id="orb">🧭</div><div class="copy"><div class="title" id="title">GPS 산책 측정 준비</div><div class="desc" id="desc">시작을 누르고 위치 권한을 허용해 주세요. 빠른 이동은 자동 제외돼요.</div></div><div class="live" id="live"><span class="dot"></span>측정 중</div><button class="btn" id="button">GPS 측정 시작</button></div><script>
let watchId=null, active=false, userStopped=false, heartbeat=null, seq=0;
function emit(payload){payload.event_id=Date.now().toString()+'-'+(++seq);window.parent.postMessage({type:'streamlit:setComponentValue',value:payload,dataType:'json'},'*');}
function height(){window.parent.postMessage({type:'streamlit:setFrameHeight',height:90},'*');}
function paint(on){active=on;document.getElementById('button').textContent=on?'측정 종료':'GPS 측정 시작';document.getElementById('button').className=on?'btn stop':'btn';document.getElementById('title').textContent=on?'숲길을 걷고 있어요!':'GPS 산책 측정 준비';document.getElementById('desc').textContent=on?'걷기와 달리기를 함께 기록해요 · '+(window.familyMember||'가족')+'님의 운동':'시작을 누르고 위치 권한을 허용해 주세요. 빠른 이동은 자동 제외돼요.';document.getElementById('live').style.display=on?'block':'none';document.getElementById('orb').textContent=on?'🌿':'🧭';height();}
function stopWatch(){if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;}if(heartbeat){clearInterval(heartbeat);heartbeat=null;}}
function startWatch(){if(watchId!==null||!navigator.geolocation)return;userStopped=false;paint(true);watchId=navigator.geolocation.watchPosition(pos=>{const c=pos.coords;emit({event:'point',lat:c.latitude,lon:c.longitude,accuracy:c.accuracy,speed:c.speed,timestamp:pos.timestamp});},err=>{stopWatch();userStopped=true;paint(false);emit({event:'error',message:err.message||'위치 정보를 가져오지 못했어요.'});},{enableHighAccuracy:true,maximumAge:1000,timeout:20000});if(!heartbeat)heartbeat=setInterval(()=>emit({event:'tick',timestamp:Date.now()}),5000);}
document.getElementById('button').addEventListener('click',()=>{if(active){userStopped=true;stopWatch();paint(false);emit({event:'stopped',timestamp:Date.now()});}else{userStopped=false;paint(true);emit({event:'started',timestamp:Date.now()});setTimeout(startWatch,350);}});
window.addEventListener('message',event=>{const d=event.data;if(!d||d.type!=='streamlit:render')return;window.familyMember=(d.args&&d.args.member)||'가족';if(d.args&&d.args.active){if(!userStopped)startWatch();}else{if(active)stopWatch();userStopped=false;paint(false);}});
window.parent.postMessage({type:'streamlit:componentReady',apiVersion:1},'*');height();
</script></body></html>'''
(COMPONENT_DIR / "index.html").write_text(COMPONENT_HTML, encoding="utf-8")
gps_tracker = components.declare_component("family_forest_gps_tracker", path=str(COMPONENT_DIR))


def default_data():
    return {"members": ["나", "가족 1", "가족 2"], "activities": [], "rewards": {}}


def github_configured():
    try:
        return bool(st.secrets.get("GITHUB_TOKEN") and st.secrets.get("GITHUB_REPO"))
    except Exception:
        return False


def github_settings():
    return {
        "token": st.secrets["GITHUB_TOKEN"],
        "repo": st.secrets["GITHUB_REPO"],
        "branch": st.secrets.get("GITHUB_BRANCH", "main"),
        "path": st.secrets.get("GITHUB_DATA_PATH", "family_run_data.json"),
    }


def load_data():
    if github_configured():
        cfg = github_settings()
        url = f"https://api.github.com/repos/{cfg['repo']}/contents/{cfg['path']}"
        headers = {"Authorization": f"Bearer {cfg['token']}", "Accept": "application/vnd.github+json"}
        try:
            response = requests.get(url, headers=headers, params={"ref": cfg["branch"]}, timeout=15)
            if response.status_code == 404:
                return default_data(), None, "github"
            response.raise_for_status()
            payload = response.json()
            data = json.loads(base64.b64decode(payload["content"]).decode("utf-8"))
            data.setdefault("members", [])
            data.setdefault("activities", [])
            data.setdefault("rewards", {})
            return data, payload.get("sha"), "github"
        except Exception as exc:
            st.error(f"공유 기록을 불러오지 못했어요: {exc}")
            st.stop()
    if DATA_FILE.exists():
        try:
            data = json.loads(DATA_FILE.read_text(encoding="utf-8"))
            data.setdefault("members", [])
            data.setdefault("activities", [])
            data.setdefault("rewards", {})
            return data, None, "local"
        except Exception:
            pass
    return default_data(), None, "local"


def save_data(data, sha, storage):
    content = json.dumps(data, ensure_ascii=False, indent=2)
    if storage == "github":
        cfg = github_settings()
        url = f"https://api.github.com/repos/{cfg['repo']}/contents/{cfg['path']}"
        headers = {"Authorization": f"Bearer {cfg['token']}", "Accept": "application/vnd.github+json"}
        payload = {"message": "Update family forest challenge", "content": base64.b64encode(content.encode("utf-8")).decode("ascii"), "branch": cfg["branch"]}
        if sha:
            payload["sha"] = sha
        response = requests.put(url, headers=headers, json=payload, timeout=20)
        if response.status_code in (409, 422):
            raise RuntimeError("동시에 기록이 저장됐어요. 페이지를 새로고침한 뒤 다시 시도해 주세요.")
        response.raise_for_status()
        return response.json().get("content", {}).get("sha")
    DATA_FILE.write_text(content, encoding="utf-8")
    return None


def persist(updated, sha, storage):
    try:
        save_data(updated, sha, storage)
        return None
    except Exception as exc:
        return str(exc)


def week_start(day):
    return day - timedelta(days=day.weekday())


def current_week_key():
    return week_start(date.today()).isoformat()


def week_activities(data):
    start = current_week_key()
    end = (date.fromisoformat(start) + timedelta(days=7)).isoformat()
    return [a for a in data["activities"] if start <= a.get("date", "") < end]


def totals_by_member(members, activities):
    totals = {name: 0.0 for name in members}
    for activity in activities:
        name = activity.get("member")
        if name in totals:
            totals[name] += float(activity.get("distance", 0))
    return totals


def haversine_km(lat1, lon1, lat2, lon2):
    radius = 6371.0088
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dlat, dlon = math.radians(lat2 - lat1), math.radians(lon2 - lon1)
    a = math.sin(dlat / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dlon / 2) ** 2
    return radius * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))


