    st.session_state.last_component_event = gps_event.get("event_id")
    event = gps_event.get("event")
    if event == "started":
        reset_tracking()
        st.session_state.tracking_active = True
        st.session_state.tracking_member = selected_member
        st.session_state.tracking_started_at = int(gps_event.get("timestamp", datetime.now().timestamp() * 1000))
    elif event == "point":
        if not st.session_state.tracking_active:
            reset_tracking()
            st.session_state.tracking_active = True
            st.session_state.tracking_member = selected_member
            st.session_state.tracking_started_at = int(gps_event.get("timestamp", datetime.now().timestamp() * 1000))
        current = {
            "lat": float(gps_event.get("lat", 0)),
            "lon": float(gps_event.get("lon", 0)),
            "accuracy": float(gps_event.get("accuracy") or 9999),
            "timestamp": int(gps_event.get("timestamp", 0)),
            "speed": gps_event.get("speed"),
        }
        previous = st.session_state.last_position
        if previous:
            elapsed = (current["timestamp"] - previous["timestamp"]) / 1000.0
            segment_km = haversine_km(previous["lat"], previous["lon"], current["lat"], current["lon"])
            computed_speed = (segment_km * 3600 / elapsed) if elapsed > 0 else 0
            reported_speed = float(current["speed"]) * 3.6 if current["speed"] is not None else 0
            fastest_speed = max(computed_speed, reported_speed)
            accuracy_ok = current["accuracy"] <= 40 and previous["accuracy"] <= 40
            if elapsed > 0 and elapsed <= 180 and accuracy_ok:
                if fastest_speed > SPEED_LIMIT_KMH:
                    st.session_state.ignored_fast += 1
                elif segment_km >= 0.004:
                    st.session_state.tracking_distance += segment_km
                    st.session_state.tracking_points += 1
        st.session_state.last_position = current
    elif event == "stopped":
        distance_km = float(st.session_state.tracking_distance)
        member_name = st.session_state.tracking_member or selected_member
        if distance_km >= 0.02:
            updated = json.loads(json.dumps(data, ensure_ascii=False))
            duration = max(0, int((int(gps_event.get("timestamp", datetime.now().timestamp() * 1000)) - int(st.session_state.tracking_started_at or gps_event.get("timestamp", 0))) / 1000))
            updated["activities"].append({"id": datetime.now().strftime("%Y%m%d%H%M%S%f"), "member": member_name, "distance": round(distance_km, 3), "date": date.today().isoformat(), "duration_seconds": duration, "source": "GPS"})
